change_extrusion_role_gcode:
{if last_extrusion_role == "Mixed" && layer_num <= 1}
; first extrusion of the print, the nozzle is on the exact start point: seal it on the bed, heat it, start 5C below the target
G0 Z0 F240
M104 S{nozzle_temperature_initial_layer[current_extruder]}
TEMPERATURE_WAIT SENSOR=extruder{if current_extruder == 1}1{endif} MINIMUM={nozzle_temperature_initial_layer[current_extruder] - 5}
{if plate_name =~/.*IDEXDupl.*/ || plate_name =~/.*IDEXCopy.*/ || plate_name =~/.*IDEXMirr.*/}
TEMPERATURE_WAIT SENSOR=extruder1 MINIMUM={nozzle_temperature_initial_layer[current_extruder] - 5}
{endif}
G0 Z{layer_z} F600
{endif}
